import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, sin, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const root = new Group();
  root.name = config.id || 'pricing-card-1';
  root.userData.handlers = {};

  const timelines = [];
  const primitiveResults = [];
  const ownedResources = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const hexRgb = (hex) => {
    const color = new Color(hex);
    return vec3(color.r, color.g, color.b);
  };

  const cardGeometry = new PlaneGeometry(2.7, 1.55, 1, 1);
  const cardMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    opacity: 1
  });

  const cardUv = uv();
  const gradientMix = smoothstep(0.0, 1.0, cardUv.y);
  const engineeredGradient = mix(
    hexRgb(colors.surface),
    hexRgb(colors.ink),
    gradientMix
  );
  const grain = sin(
    cardUv.x.mul(173.0).add(cardUv.y.mul(97.0))
  ).mul(0.012);
  const grainColor = vec3(grain, grain, grain);

  cardMaterial.colorNode = vec4(
    engineeredGradient.add(grainColor),
    1.0
  );

  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'pricing-card-1-surface';
  card.position.z = 0;
  root.add(card);
  ownedResources.push(cardGeometry, cardMaterial);

  const edgeGeometry = new PlaneGeometry(0.055, 1.2, 1, 1);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.name = 'pricing-card-1-signal-edge';
  edge.position.set(-1.28, 0, 0.012);
  root.add(edge);
  ownedResources.push(edgeGeometry, edgeMaterial);

  const topRuleGeometry = new PlaneGeometry(1.1, 0.018, 1, 1);
  const topRuleMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.52
  });
  const topRule = new Mesh(topRuleGeometry, topRuleMaterial);
  topRule.name = 'pricing-card-1-paper-rule';
  topRule.position.set(-0.55, 0.47, 0.013);
  root.add(topRule);
  ownedResources.push(topRuleGeometry, topRuleMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  let textOffset = 0.08;

  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.name = `pricing-card-1-${item.role || 'text'}`;
    textObject.position.set(-1.03, textOffset, 0.025);
    root.add(textObject);
    textOffset -= 0.28;
  }

  const imageUrl = config.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (disposed || !loadedTexture) return;

      const decorGeometry = new PlaneGeometry(0.82, 0.82, 1, 1);
      const decorMaterial = new MeshBasicNodeMaterial({
        transparent: true,
        depthWrite: false,
        opacity: 0.72
      });

      decorMaterial.colorNode = texture(loadedTexture);

      const decor = new Mesh(decorGeometry, decorMaterial);
      decor.name = 'pricing-card-1-orb-decoration';
      decor.position.set(0.78, -0.08, 0.028);
      root.add(decor);

      ownedResources.push(decorGeometry, decorMaterial, loadedTexture);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const primitiveFactory = ctx.primitives?.[primitive.name];
    if (typeof primitiveFactory !== 'function') continue;

    const result = primitiveFactory(root, primitive.params);
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') {
        timeline.kill();
      }
    }

    for (const result of primitiveResults) {
      if (result && typeof result.cleanup === 'function') {
        result.cleanup();
      }
    }

    root.traverse((object) => {
      if (object.userData?.cleanup && object.userData.cleanup !== root.userData.cleanup) {
        try {
          object.userData.cleanup();
        } catch (_) {}
      }
    });

    for (const resource of ownedResources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    root.clear();
  };

  return root;
}
